import{a as e,c as t,i as n}from"./app-De1cKXWh.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-11-network.html","title":"Docker 网络——从 localhost 不通滚到能用名字互访","lang":"zh-CN","frontmatter":{"title":"Docker 网络——从 localhost 不通滚到能用名字互访","sidebarGroup":"Docker 系列","shortTitle":"11 Docker 网络","order":11,"date":"2026-08-22T00:00:00.000Z","category":"云原生","tag":["Docker","云原生","Docker系列"],"description":"师生对话实录课：0 基础学生与教学大师的 Docker Network 控制台逐字稿，从「为什么 localhost 不通」一路滚到「能用名字互访」，实验全部 WSL 实机真跑。","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Docker 网络——从 localhost 不通滚到能用名字互访\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-08-22T00:00:00.000Z\\",\\"dateModified\\":\\"2026-08-22T00:25:59.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Corey\\",\\"url\\":\\"https://www.code-corey.com\\"}]}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-11-network.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"Docker 网络——从 localhost 不通滚到能用名字互访"}],["meta",{"property":"og:description","content":"师生对话实录课：0 基础学生与教学大师的 Docker Network 控制台逐字稿，从「为什么 localhost 不通」一路滚到「能用名字互访」，实验全部 WSL 实机真跑。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-22T00:25:59.000Z"}],["meta",{"property":"article:tag","content":"Docker系列"}],["meta",{"property":"article:tag","content":"云原生"}],["meta",{"property":"article:tag","content":"Docker"}],["meta",{"property":"article:published_time","content":"2026-08-22T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-22T00:25:59.000Z"}]]},"git":{"createdTime":1786937104000,"updatedTime":1787358359000,"contributors":[{"name":"chengongyi","username":"chengongyi","email":"2363613998@qq.com","commits":8,"url":"https://github.com/chengongyi"},{"name":"Corey C","username":"","email":"2363613998@qq.com","commits":1}]},"readingTime":{"minutes":44.16,"words":13249},"filePathRelative":"云原生/docker/docker-11-network.md","excerpt":"<blockquote>\\n<p><strong>Docker 系列 · 第 11/24 篇</strong><br>\\n上一篇：<a href=\\"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-10-harbor-usage\\">《Harbor 私有仓库使用》</a> · 下一篇：<a href=\\"/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-12-data-persistence\\">《Docker 数据持久化——从容器一删库没了，滚到三种挂载》</a></p>\\n</blockquote>\\n<hr>\\n<h1>课堂实录（控制台逐字稿）</h1>"}`),a={name:`docker-11-network.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p><strong>Docker 系列 · 第 11/24 篇</strong><br> 上一篇：<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-10-harbor-usage">《Harbor 私有仓库使用》</a> · 下一篇：<a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-12-data-persistence">《Docker 数据持久化——从容器一删库没了，滚到三种挂载》</a></p></blockquote><hr><h1 id="课堂实录-控制台逐字稿" tabindex="-1"><a class="header-anchor" href="#课堂实录-控制台逐字稿"><span>课堂实录（控制台逐字稿）</span></a></h1><blockquote><p><strong>体例说明</strong>：本文是师生对话的<strong>控制台回放逐字稿</strong>，按时间顺序记录——学生原话、老师原文（与控制台输出一字不差）、操作记录（实验、建文件），不加整理。环境：Windows 10 + WSL 里跑 Docker，所有实验真机执行，输出不造假。</p></blockquote><hr><h2 id="【2026-08-22-·-第-1-次对话】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-1-次对话】"><span>【2026-08-22 · 第 1 次对话】</span></a></h2><h3 id="学生原话" tabindex="-1"><a class="header-anchor" href="#学生原话"><span>学生原话</span></a></h3><blockquote><p>[互动式教学-教室场景模拟]</p><p>你是一名全球最为顶尖的教学大师，精通各类技术。你的目标就是培养我某一个专业领域的大师。而我是一名0基础的学生。</p><p>在开始教授前，你会通过获取最新的官方文档，通过西蒙学习法一点点拆碎，形成自己的教学大纲，确保这个教学大纲我学习完后，可以成为一个资深的技术专家。<br> 然后你使用费曼技巧，给我讲解最为基本的知识块，而你每次只会给我讲解一个概念，如果我有问题，我就会提出来问你，如果没有问题则继续讲解。</p><h2 id="要求" tabindex="-1"><a class="header-anchor" href="#要求"><span>要求：</span></a></h2><p>1、我们之间的所有对话记录都要保留下来，做成那种课堂问答的形式。每次我们对话完，都要及时的写入文件中。<br> 2、我的要的是控制台回放的逐字稿：学生原话、老师原文（含控制台里那版完整的开场白）、操作记录（实验、建文件），全部按时间顺序，不加整理。</p><p>我们需要学习的内容是 [docker的Network]<br> 把记录保存在，覆盖这篇文中 [E:\\MyGithub\\langkemaoxin.github.io\\src\\云原生\\docker\\docker-11-network.md]</p><p>开始教学</p></blockquote><h3 id="操作记录-课前备课-按时间顺序" tabindex="-1"><a class="header-anchor" href="#操作记录-课前备课-按时间顺序"><span>操作记录（课前备课，按时间顺序）</span></a></h3><ol><li>读 <code>E:\\MyGithub\\langkemaoxin.github.io\\src\\云原生\\docker\\docker-11-network.md</code> → 空文件（仅两行空行），确认可覆盖，无旧内容丢失。</li><li>WebFetch 抓 <code>https://docs.docker.com/engine/network/</code> → 被网络策略拦截（&quot;Unable to verify if domain <a href="http://docs.docker.com" target="_blank" rel="noopener noreferrer">docs.docker.com</a> is safe to fetch&quot;）。</li><li>改用 webReader 成功抓取官方 Networking overview 全文（页面元数据 <code>og:updated_time: 2026-07-21</code>，即 2026 年 7 月 21 日更新的现行版）。</li><li><code>ls src/云原生/docker/</code> 摸清系列结构（24 篇闭环 + 2 附录）；读 <code>docker-12-data-persistence.md</code> 头部确认 frontmatter 与前后篇导航格式，本篇标题沿用《Docker 网络——从 localhost 不通滚到能用名字互访》以保持导航一致。</li><li>读目录下历史残留 <code>_lab_net_out.txt</code> → 内容是一次失败的 WSL 实验脚本报错（<code>set: pipefail: invalid option name</code>，PowerShell→wsl 的 <code>\\r</code> 换行符坑），与本次课程无关，留档未删。</li><li>建本文件，写入第 1 次对话实录。</li></ol><h3 id="老师原文-控制台开场白-教学大纲-第-1-课" tabindex="-1"><a class="header-anchor" href="#老师原文-控制台开场白-教学大纲-第-1-课"><span>老师原文（控制台开场白 + 教学大纲 + 第 1 课）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p>同学，你好。我是这门课的老师。</p><p>在开讲之前，我先交代一下我是怎么备这门课的，你可以把它当成这门课的&quot;入学须知&quot;：</p><p>我备课的方式是这样的——先去把 Docker 官方文档里 Networking 的全部内容拉下来通读（我拿到的是 2026 年 7 月 21 日更新的现行版，不是道听途说的旧版），然后用西蒙学习法把它拆碎：官方文档是按&quot;参考手册&quot;组织 的，适合查，不适合学；我会把它的知识重新排成一条&quot;从已知到未知&quot;的线，每一课只新增一个知识点，后面的课只建立在前面讲过的东西上。等这条线走完，你手里就有了官方文档的全部内容，而且是按&quot;人脑能吸收&quot;的顺序排好的。</p><p>讲的方式是费曼技巧：我每节课只讲<strong>一个</strong>概念，用大白话讲，讲完就停。你有问题就问，没问题我们就进下一课。课里的每个实验我都会在这台机器上真跑，你看到的每一行输出都是真的——这台机器上跑不了的，我会明说是演示，绝不编造输出。</p><p>下面是教学大纲，一共 20 课，四个阶段，难度是一条上坡路：</p><h2 id="教学大纲-依据-docs-docker-com-engine-network-2026-07-21-版拆解" tabindex="-1"><a class="header-anchor" href="#教学大纲-依据-docs-docker-com-engine-network-2026-07-21-版拆解"><span>教学大纲（依据 <a href="http://docs.docker.com/engine/network%EF%BC%8C2026-07-21" target="_blank" rel="noopener noreferrer">docs.docker.com/engine/network，2026-07-21</a> 版拆解）</span></a></h2><p><strong>阶段一：默认网络——先看清&quot;容器为什么是台小电脑&quot;</strong></p><ol><li>为什么容器需要网络——三个问题一根线（今天这课）</li><li>容器眼里的网络——网卡、IP、网关、路由表、DNS 五件套</li><li>docker0 与默认 bridge——宿主机上到底多了什么东西（实验）</li><li>默认 bridge 实战——两个容器用 IP 互 ping（实验）</li><li>容器怎么上网——masquerading（NAT 伪装）</li><li>端口发布 <code>-p</code>——外面的世界怎么进来（实验）</li></ol><p><strong>阶段二：自定义网络——生产环境真正的用法</strong></p><ol start="7"><li>默认 bridge 的痛——只能用 IP，不能用名字（实验）</li><li>自定义网络与内嵌 DNS（127.0.0.11）——用名字互访（实验）</li><li>网络即隔离墙——两个网络之间为什么不通</li><li>一个容器连多个网络——<code>docker network connect</code></li></ol><p><strong>阶段三：其他网络驱动——换掉&quot;虚拟交换机&quot;这个方案本身</strong></p><ol start="11"><li><code>none</code>——彻底断网给谁用</li><li><code>host</code>——不要小电脑的网络了，直接用宿主机的</li><li><code>container:</code> 模式——两个容器共用一副网络</li><li><code>macvlan</code> / <code>ipvlan</code>——容器伪装成一台物理设备</li><li><code>overlay</code>——跨主机的容器大网（概念课）</li></ol><p><strong>阶段四：运维进阶——管网络的人</strong></p><ol start="16"><li>网络命令全家桶——<code>ls</code> / <code>inspect</code> / <code>create</code> / <code>rm</code> / <code>prune</code></li><li>子网规划与 <code>default-address-pools</code></li><li>DNS 进阶——<code>--dns</code> / <code>--hostname</code> / <code>--alias</code> / <code>gw-priority</code></li><li>IPv6 网络开关</li><li>毕业设计——综合实战串讲</li></ol><hr><p>好，现在开始第一课。深呼吸，我们从零开始。</p><h1 id="第-1-课-为什么容器需要网络" tabindex="-1"><a class="header-anchor" href="#第-1-课-为什么容器需要网络"><span>第 1 课：为什么容器需要网络？</span></a></h1><h2 id="从一个你会立刻撞上的问题讲起" tabindex="-1"><a class="header-anchor" href="#从一个你会立刻撞上的问题讲起"><span>从一个你会立刻撞上的问题讲起</span></a></h2><p>假设你已经在自己电脑上跑起来了两个容器（跑的命令现在不用管，后面课里会教）：</p><ul><li>一个 <strong>Nginx</strong> 容器——网页服务器</li><li>一个 <strong>Redis</strong> 容器——数据库</li></ul><p>它们就跑在同一台电脑上，肩并肩。现在 Nginx 想把数据存进 Redis，问题来了：<strong>它俩怎么&quot;说话&quot;？</strong></p><p>你的第一反应多半是：同一台电脑嘛，用 <code>localhost</code>（也就是 <code>127.0.0.1</code>）连过去呗。这个直觉非常自然，但在容器世界<strong>恰好是错的</strong>。</p><h2 id="心智模型-每个容器是一台配了网卡的独立小电脑" tabindex="-1"><a class="header-anchor" href="#心智模型-每个容器是一台配了网卡的独立小电脑"><span>心智模型：每个容器是一台配了网卡的独立小电脑</span></a></h2><p>为什么错？回想一下你已经学过的容器知识（隔离）：每个容器都是一个被隔离出来的环境——有自己的文件系统、自己的进程空间。今天我要在这个模型上<strong>加一块砖</strong>：容器还有<strong>自己的网卡、自己的 IP 地址</strong>。</p><p>所以更准确的心智模型是：</p><blockquote><p>你的电脑不是一台电脑，而是&quot;一台真电脑 + N 台迷你小电脑&quot;。每台小电脑都有自己的一块网卡，插在 Docker 给你装的&quot;虚拟交换机&quot;上。</p></blockquote><p>带着这个模型再看 <code>localhost</code>：<code>localhost</code> 的意思是&quot;<strong>我自己这台电脑</strong>&quot;。Nginx 容器里的 localhost，指的是 <strong>Nginx 这台小电脑自己</strong>——不是宿主机，更不是隔壁的 Redis。所以在 Nginx 容器里连 <code>localhost:6379</code>，等于在小电脑里自己跟自己握 手，Redis 根本听不见。</p><p>这就是容器网络要解决的第一个问题：<strong>隔离出来的小电脑们，怎么互相联网？</strong></p><h2 id="三个问题一根线" tabindex="-1"><a class="header-anchor" href="#三个问题一根线"><span>三个问题一根线</span></a></h2><p>光解决&quot;互相联网&quot;还不够。把容器网络想全，一共三个问题，也是我们这门课的骨架：</p><ol><li><strong>容器 ↔ 容器</strong>：Nginx 怎么访问 Redis？（用 IP？用名字？）</li><li><strong>外界 → 容器</strong>：你的浏览器在真电脑上，Nginx 在小电脑里，浏览器怎么打开 Nginx 的网页？——剧透：默认也<strong>进不去</strong>，需要&quot;端口发布&quot;（第 6 课）。</li><li><strong>容器 → 外界</strong>：容器里想 <code>apt-get install</code> 装个软件、想调外网 API，能出去吗？——这个默认<strong>可以</strong>，Docker 偷偷帮你做了&quot;伪装上网&quot;（第 5 课）。</li></ol><p>一门 20 课的课，其实就是把这三个问题一层层剥开。</p><h2 id="官方文档的第一句话" tabindex="-1"><a class="header-anchor" href="#官方文档的第一句话"><span>官方文档的第一句话</span></a></h2><p>Docker 官方文档对容器网络的定义就一句话（我直译）：</p><blockquote><p>Container networking refers to the ability for containers to connect to and communicate with each other, and with non-Docker network services.</p><p>容器网络，指的是容器之间、以及容器与非 Docker 的网络服务之间，建立连接并通信的能力。</p></blockquote><p>注意后半句&quot;与非 Docker 服务通信&quot;——不只是容器互连，容器还要能跟你局域网里的 MySQL、能跟互联网上的 API 说话。三个问题对应上了。</p><p>还有一个反直觉但极其重要的事实，官方原话是：</p><blockquote><p>A container has no information about what kind of network it&#39;s attached to, or whether its network peers are also Docker containers.</p><p>容器根本不知道自己连的是什么网络，也不知道对面那台是不是容器。</p></blockquote><p>那容器能看到什么？官方的清单是：<strong>一块网络接口（网卡）+ 一个 IP 地址 + 一个网关 + 一张路由表 + DNS 服务</strong>。就这些。</p><p>翻译成人话：容器开机后看到的东西，和你给一台真电脑插上网线后看到的东西<strong>一模一样</strong>。为什么这么设计？因为容器的整个承诺就是&quot;应用不用改，搬进容器照样跑&quot;。如果容器里的程序还要写特殊代码才能上网，这个承诺就破了。所以 Docker 把网络也伪装成&quot;一台普通电脑该有的样子&quot;——这是整个容器网络设计的<strong>第一性原理</strong>，后面 19 课的所有设计都从这句话推出来。</p><h2 id="本课小结" tabindex="-1"><a class="header-anchor" href="#本课小结"><span>本课小结</span></a></h2><ul><li>心智模型：一台真电脑 + N 台带独立网卡的迷你小电脑</li><li><code>localhost</code> 在容器里 = 小电脑自己，不是宿主机</li><li>三个问题一根线：容器↔容器、外界→容器、容器→外界</li><li>第一性原理：容器眼里，网络就长成&quot;一台普通电脑&quot;的样子</li></ul><h2 id="课后思考题-不查资料-凭直觉答我" tabindex="-1"><a class="header-anchor" href="#课后思考题-不查资料-凭直觉答我"><span>课后思考题（不查资料，凭直觉答我）</span></a></h2><p>你在宿主机的浏览器里访问 <code>http://localhost:80</code>，Nginx 容器里确实监听着 80 端口。<strong>默认情况下，网页能打开吗？为什么？</strong></p><p>把你的答案和理由告诉我——答对答错都没关系，我要看的是你的直觉走到哪了。然后我们进第 2 课。</p><hr><h2 id="【2026-08-22-·-第-2-次对话】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-2-次对话】"><span>【2026-08-22 · 第 2 次对话】</span></a></h2><h3 id="学生原话-1" tabindex="-1"><a class="header-anchor" href="#学生原话-1"><span>学生原话</span></a></h3><blockquote><p>默认是打不开的，因为如果不做任何设置，我打开的http://localhost:80只是打开我本机的地址，和Docker容器没有关系</p></blockquote><h3 id="操作记录-第-2-课课前实验-全部真机执行-环境-windows-10-wsl-内-docker-engine-29-1-3" tabindex="-1"><a class="header-anchor" href="#操作记录-第-2-课课前实验-全部真机执行-环境-windows-10-wsl-内-docker-engine-29-1-3"><span>操作记录（第 2 课课前实验，全部真机执行，环境：Windows 10 + WSL 内 Docker Engine 29.1.3）</span></a></h3><ol><li><code>wsl -e bash -lc &#39;docker version --format &quot;Server: {{.Server.Version}}&quot;&#39;</code> → <code>Server: 29.1.3</code>（daemon 在线）</li><li><code>docker run --rm alpine ip addr</code> → 输出 <code>lo: 127.0.0.1/8</code> 与 <code>eth0@if40: 172.17.0.9/16, link/ether f2:a5:bb:9e:02:ca</code></li><li><code>docker run --rm alpine ip route</code> → 输出两条路由：<code>default via 172.17.0.1 dev eth0</code> 与 <code>172.17.0.0/16 dev eth0 scope link src 172.17.0.9</code></li><li><code>docker run --rm alpine cat /etc/resolv.conf</code> → <code>nameserver 223.5.5.5 / 114.114.114.114 / 8.8.8.8</code>，头部注释含 <code>Generated by Docker Engine.</code> 与 <code>Based on host file: &#39;/etc/resolv.conf&#39; (legacy)</code></li><li><code>docker run --rm alpine hostname</code> → <code>516d68c0d34d</code>（容器 ID 短哈希）</li><li>本对话实录追加进本文件。</li></ol><h3 id="老师原文-判卷-第-2-课" tabindex="-1"><a class="header-anchor" href="#老师原文-判卷-第-2-课"><span>老师原文（判卷 + 第 2 课）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p><strong>先判卷。</strong></p><p>结论：<strong>对</strong>，默认打不开。✓</p><p>理由：<strong>对了一半</strong>。你说&quot;localhost 是我本机的地址&quot;——这部分完全正确。但&quot;和 Docker 容器没有关系&quot;这句，把墙说得太厚了。</p><p>精确版是这样的：浏览器访问 <code>localhost:80</code>，找的是<strong>宿主机自己的 80 端口</strong>。而宿主机的 80 端口上，没有任何进程在监听——Nginx 监听的是<strong>另一台&quot;小电脑&quot;的 80 端口</strong>。注意这里的坑：<strong>每台&quot;电脑&quot;有自己独立的一套端口空间</strong>。宿主机的 80 号房间是空的，Nginx 坐在容器那台小电脑的 80 号房间里，两间房门牌号一样，但根本不是同一间房。</p><p>另外给你留个钩子：宿主机和容器之间其实<strong>有一扇半开的门</strong>，比你想象的近得多——第 3 课你会亲眼看到。现在先记住：默认打不开，因为敲门敲错了门。</p><p>80 分。比我带过的大多数初学者的第一答好——多数人答&quot;能打开，因为就在本机&quot;。</p><p>那我们进第 2 课。</p><hr><h1 id="第-2-课-容器眼里的网络——五件套" tabindex="-1"><a class="header-anchor" href="#第-2-课-容器眼里的网络——五件套"><span>第 2 课：容器眼里的网络——五件套</span></a></h1><p>上一课官方文档说了，容器能看到的东西只有五样：<strong>一块网卡、一个 IP、一个网关、一张路由表、DNS 服务</strong>。</p><p>当时我说这是&quot;容器网络的全部地基&quot;。今天我们就把这五样挨个打开看——而且不是看我画图，是看<strong>真容器里跑出来的真输出</strong>。我刚在这台机器上跑了四条命令（命令本身你先不用背，先看懂输出）：</p><h2 id="实验一-网卡——ip-addr" tabindex="-1"><a class="header-anchor" href="#实验一-网卡——ip-addr"><span>实验一：网卡——<code>ip addr</code></span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker run --rm alpine ip addr</span></span>
<span class="line"><span>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN qlen 1000</span></span>
<span class="line"><span>    link/loopback 00:00:00:00:00:00</span></span>
<span class="line"><span>    inet 127.0.0.1/8 scope host lo</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>    inet6 ::1/128 scope host</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>2: eth0@if40: &lt;BROADCAST,MULTICAST,UP,LOWER_UP,M-DOWN&gt; mtu 1500 qdisc noqueue state UP</span></span>
<span class="line"><span>    link/ether f2:a5:bb:9e:02:ca brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 172.17.0.9/16 brd 172.17.255.255 scope global eth0</span></span>
<span class="line"><span>       valid_lft forever preferred_lft forever</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这台小电脑开机后一共有<strong>两块网卡</strong>：</p><ul><li><code>lo</code>——&quot;自言自线路&quot;。挂在上面的地址就是 <code>127.0.0.1</code>。<strong>上一课的 localhost 谜底就在这</strong>：容器里的 localhost，就是这个 lo，绕一圈回到自己，永远出不了这台小电脑。</li><li><code>eth0</code>——真正的对外网口，插在 Docker 那台&quot;虚拟交换机&quot;上。它有三个看点： <ul><li><strong>IP 地址 <code>172.17.0.9</code></strong>：门牌号。注意，我们<strong>从没申请过 IP</strong>，容器一开机它就自动有了——是 Docker 从一个&quot;号码池&quot;里动态租给它的。</li><li><strong>MAC 地址 <code>f2:a5:bb:9e:02:ca</code></strong>：网卡的出厂编号，顺带认识一下，本文不展开。</li><li><strong>名字后面的 <code>@if40</code></strong>：现在你只需要记住这个彩蛋存在——eth0 不是一根线，是一根<strong>线的一半</strong>，另一半在宿主机上，编号 40。第 3 课揭晓它。</li></ul></li></ul><p>还有一个细节值得停下来看一眼：为什么是 <code>172.17.0.9</code>，不是 <code>172.17.0.2</code>？——因为这台机器的 Docker 网络里已经有别的容器先占了坑。<strong>IP 是先到先得动态分配的</strong>，容器重启后号码还可能变。现在把这个事实放兜里，第 7 课它会变成一场事故。</p><h2 id="实验二-路由表与网关——ip-route" tabindex="-1"><a class="header-anchor" href="#实验二-路由表与网关——ip-route"><span>实验二：路由表与网关——<code>ip route</code></span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker run --rm alpine ip route</span></span>
<span class="line"><span>default via 172.17.0.1 dev eth0</span></span>
<span class="line"><span>172.17.0.0/16 dev eth0 scope link  src 172.17.0.9</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>整张表就两行，但这两行就是这台小电脑<strong>所有出门决策的全部规则</strong>：</p><ul><li>第二行先看（更具体的规则优先）：<strong>目的地在 <code>172.17.0.0/16</code> 这个网段里的（也就是同小区的邻居），直接从 eth0 喊话</strong>，不用经过任何人。<code>scope link</code> 的意思就是&quot;近到一根线直接连着&quot;。</li><li>第一行兜底规则 <code>default</code>：<strong>其余的一切目的地，交给 <code>172.17.0.1</code>，从 eth0 出去</strong>。</li></ul><p>而 <code>172.17.0.1</code> 这个地址，就是<strong>网关（gateway）</strong>——小区大门。它是谁？它是 Docker 那台&quot;虚拟交换机&quot;在宿主机一侧的地址。所有出小区的流量（上互联网、去别的网段）都从它手里过。第 3 课我们会站在宿主机上亲眼看到这扇门。</p><p>路由表和网关的关系一句话总结：<strong>路由表是规则清单，网关是清单里那条兜底规则指定的收件人。</strong></p><h2 id="实验三-dns——cat-etc-resolv-conf" tabindex="-1"><a class="header-anchor" href="#实验三-dns——cat-etc-resolv-conf"><span>实验三：DNS——<code>cat /etc/resolv.conf</code></span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker run --rm alpine cat /etc/resolv.conf</span></span>
<span class="line"><span># Generated by Docker Engine.</span></span>
<span class="line"><span># This file can be edited; Docker Engine will not make further changes once it</span></span>
<span class="line"><span># has been modified.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nameserver 223.5.5.5</span></span>
<span class="line"><span>nameserver 114.114.114.114</span></span>
<span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Based on host file: &#39;/etc/resolv.conf&#39; (legacy)</span></span>
<span class="line"><span># Overrides: [nameservers]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>网络世界只认 IP，但人只记得住名字。所以需要<strong>查号台</strong>：你报 <code>www.baidu.com</code>，它告诉你 IP。<code>nameserver</code> 开头的三行就是查号台的三个号码。</p><p>这里有个<strong>藏得很深的官方文档证据</strong>，最后那行注释：<code>Based on host file: &#39;/etc/resolv.conf&#39; (legacy)</code>——默认 bridge 网络上的容器，用的是<strong>宿主机 DNS 配置的一个拷贝</strong>。我这台机器（WSL）配了三个查号台：223.5.5.5（阿里）、114.114.114.114、8.8.8.8（谷歌），容器照单全收。</p><p>把&quot;默认 bridge = 拷贝宿主机的 DNS&quot;这句话放兜里，第 8 课你会发现自定义网络里这个文件会<strong>彻底变样</strong>（变成一个 Docker 自己的神秘地址），那是容器网络最好玩的一幕之一。</p><h2 id="实验四-附赠-hostname" tabindex="-1"><a class="header-anchor" href="#实验四-附赠-hostname"><span>实验四（附赠）：hostname</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker run --rm alpine hostname</span></span>
<span class="line"><span>516d68c0d34d</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这台小电脑的名字是一串乱码？——它就是<strong>容器 ID</strong>。官方文档原话：容器的 hostname 默认就是容器 ID。也就是说，小电脑出厂时顶着一个&quot;身份证号&quot;当名字，没有人类友好名。这也放兜里：第 8 课我们会看到名字在容器网络里扮演的核心角色。</p><h2 id="五件套全家福" tabindex="-1"><a class="header-anchor" href="#五件套全家福"><span>五件套全家福</span></a></h2><table><thead><tr><th>件</th><th>在哪看到的</th><th>是什么（一句话）</th></tr></thead><tbody><tr><td>网卡</td><td><code>eth0@if40</code></td><td>对外网口，插在虚拟交换机上</td></tr><tr><td>IP</td><td><code>172.17.0.9</code></td><td>动态租来的门牌号，会变</td></tr><tr><td>网关</td><td><code>172.17.0.1</code></td><td>小区大门，所有出小区流量的收件人</td></tr><tr><td>路由表</td><td><code>ip route</code> 两行</td><td>出门决策规则：邻居直呼，其余交大门</td></tr><tr><td>DNS</td><td><code>resolv.conf</code></td><td>查号台，名字换 IP</td></tr></tbody></table><p>回头看第 1 课那句第一性原理——&quot;容器眼里，网络就长成一台普通电脑的样子&quot;——现在你有实证了：这五件套，跟一台插了网线的真电脑<strong>一模一样</strong>，一件不多，一件不少。</p><h2 id="本课小结-1" tabindex="-1"><a class="header-anchor" href="#本课小结-1"><span>本课小结</span></a></h2><ul><li>localhost 谜底：容器里的 <code>127.0.0.1</code> 挂在 <code>lo</code> 网卡上，永远出不了小电脑</li><li>IP 是 Docker 动态租的（<code>.9</code> 而不是 <code>.2</code> 就是证据），<strong>别把 IP 写死</strong>——第 7 课见</li><li>路由表两行规则：同网段直连，其余交给网关 <code>172.17.0.1</code></li><li>默认 bridge 的 DNS = 宿主机配置的拷贝</li><li>容器默认 hostname = 容器 ID</li></ul><h2 id="课后思考题-不查资料-用今天学的五件套推理" tabindex="-1"><a class="header-anchor" href="#课后思考题-不查资料-用今天学的五件套推理"><span>课后思考题（不查资料，用今天学的五件套推理）</span></a></h2><p>在容器里执行 <code>curl http://www.baidu.com</code>，<strong>五件套被用到几件、按什么顺序、各干了什么活</strong>？把你能推出来说的都说给我听。</p><hr><h2 id="【2026-08-22-·-第-3-次对话】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-3-次对话】"><span>【2026-08-22 · 第 3 次对话】</span></a></h2><h3 id="学生原话-2" tabindex="-1"><a class="header-anchor" href="#学生原话-2"><span>学生原话</span></a></h3><blockquote><p>第一步应该是把百度的域名，通过DNS去换取IP地址，然后通过路由表一看，这个IP不是令居，然后再把这个请求去交给网关，网关把这个请求，顺着网卡，转发到了宿主机上。宿主机再通过自己的网卡把请求转发出去</p></blockquote><h3 id="操作记录-第-3-课课前实验-全部真机执行" tabindex="-1"><a class="header-anchor" href="#操作记录-第-3-课课前实验-全部真机执行"><span>操作记录（第 3 课课前实验，全部真机执行）</span></a></h3><ol><li>宿主机 <code>ip addr show docker0</code> → <code>inet 172.17.0.1/16</code>，MAC <code>66:c5:ef:c2:a7:88</code>——第 2 课网关之谜的答案浮出水面。</li><li><code>docker ps</code> → 机器上现存 7 个容器：<code>box1</code>、<code>box2</code>（busybox，上次课遗留，Up 42 分钟）、<code>s-net-db</code>（redis:alpine）、<code>s-net-web</code>、<code>lab-net-web</code>（nginx:alpine）、<code>jzfz-redis</code>（redis:7）、<code>jzfz-pg</code>（postgres:15）——第 2 课&quot;为什么新容器拿到 .9&quot;的答案。</li><li><code>docker exec box1 ip addr show eth0</code> → <code>2: eth0@if38 ... inet 172.17.0.7/16</code>（容器内 ifindex=2）。</li><li>宿主机 <code>ip link show type veth</code> → 7 根 <code>vethXXXXXX@if2</code>，全部 <code>master docker0</code>，其中第 38 号 <code>vetha5b2c4c@if2</code> 与 box1 的 <code>eth0@if38</code> 编号互指——7 容器恰好 7 根线。</li><li>宿主机 <code>ping -c 2 -W 1 172.17.0.7</code> → 2 发 2 收，0% 丢包，rtt 0.095ms——&quot;半开的门&quot;验证通过。</li><li><code>docker network ls</code> → <code>bridge</code> / <code>host</code> / <code>none</code> 三个默认网络 + 本机遗留的 4 个自定义网络（<code>docker_gwbridge</code>、<code>new-api_new-api-network</code>、<code>rabbitmq-cluster_default</code>、<code>rabbitmq_default</code>）。</li><li>本对话实录追加进本文件。box1/box2 保留不删，留作第 4 课互 ping 实验用。</li></ol><h3 id="老师原文-判卷-第-3-课" tabindex="-1"><a class="header-anchor" href="#老师原文-判卷-第-3-课"><span>老师原文（判卷 + 第 3 课）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p><strong>先判卷。</strong></p><p>你的推理链：<strong>DNS 换 IP → 查路由表 → 不是邻居 → 交网关 → 网关转到宿主机 → 宿主机网卡转发出去</strong>。</p><p>顺序全对，五件套用上了四件（lo 确实用不上）。88 分。今天我要在这条链上给你拧三个升级螺栓：</p><p><strong>螺栓一（嵌套）</strong>：你说&quot;第一步是 DNS 换 IP&quot;——但查号台 <code>223.5.5.5</code> 自己就<strong>不在小区里</strong>！它也是外网地址。所以&quot;问 DNS&quot;这一步，自己就要先走一遍&quot;查路由表 → 不是邻居 → 交网关&quot;。也就是说你描述的流程发生了<strong>两轮</strong>：第一轮问路（DNS 查询出门），第二轮才是真正的 HTTP 请求。DNS 不是流程外的准备动作，它本身就是第一个出门的包。</p><p><strong>螺栓二（措辞）</strong>：你说&quot;网关把请求<strong>转发到了</strong>宿主机上&quot;——今天实验会给你修正：网关不是把包转交给宿主机，<strong>网关就是宿主机本人</strong>。<code>172.17.0.1</code> 这扇&quot;小区大门&quot;，其实是一块<strong>长在宿主机身上的网卡</strong>。门不是通向宿主机的门，门就是宿主机。</p><p><strong>螺栓三（魔术预告）</strong>：你说&quot;宿主机通过自己的网卡把请求转发出去&quot;——大方向对，但&quot;转发&quot;这个词里藏着整个容器出网最大的一个魔术：宿主机<strong>不是原样转发的</strong>，它在出门前偷偷改了包裹上的寄件人。改成了谁？为什么不改就收不到回信？第 5 课专门拆这个魔术。</p><p>好，三个螺栓都拧在第 3、5 课的位置上。现在进第 3 课。</p><hr><h1 id="第-3-课-docker0-与默认-bridge——宿主机上到底多了什么" tabindex="-1"><a class="header-anchor" href="#第-3-课-docker0-与默认-bridge——宿主机上到底多了什么"><span>第 3 课：docker0 与默认 bridge——宿主机上到底多了什么</span></a></h1><h2 id="视角切换" tabindex="-1"><a class="header-anchor" href="#视角切换"><span>视角切换</span></a></h2><p>前两课我们一直<strong>站在容器小电脑里</strong>往外看：看到了五件套、看到了大门 172.17.0.1、看到了一根&quot;有另一半的网线&quot; eth0@if40。</p><p>今天我们爬出小电脑，<strong>站到宿主机（真电脑）上</strong>，回答一个问题：Docker 装好、跑起来之后，宿主机上<strong>多了哪些东西</strong>？</p><h2 id="实验一-小区大门的真身" tabindex="-1"><a class="header-anchor" href="#实验一-小区大门的真身"><span>实验一：小区大门的真身</span></a></h2><p>在宿主机上执行（我真机跑了）：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ ip addr show docker0</span></span>
<span class="line"><span>4: docker0: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue state UP group default</span></span>
<span class="line"><span>    link/ether 66:c5:ef:c2:a7:88 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 172.17.0.1/16 brd 172.17.255.255 scope global docker0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看到了吗——宿主机上有一块网卡，名字叫 <strong>docker0</strong>，IP 是 <strong>172.17.0.1</strong>。</p><p>第 2 课容器里看到的&quot;小区大门 172.17.0.1&quot;，谜底揭晓：<strong>它就是宿主机上的 docker0 这块网卡</strong>。大门不是通往宿主机的门，大门就是宿主机伸进小区的一只手。</p><h2 id="是什么-bridge-网桥" tabindex="-1"><a class="header-anchor" href="#是什么-bridge-网桥"><span>是什么：bridge（网桥）</span></a></h2><p>那 docker0 这块网卡是什么东西？它的类型是 <strong>bridge（网桥）</strong>。</p><p>是什么：网桥是 Linux 内核自带的一个功能——<strong>用软件模拟出来的交换机</strong>。物理交换机你可能在机房见过：一排网口，插几根网线进去，插在上面的设备就互通。网桥就是同样功能的软件版：一块&quot;虚拟网卡&quot;，别的网卡可以&quot;插&quot;在它上面，插上的设备彼此互通。</p><p>为什么 Docker 要用它：容器一台一台地起、一删就没，你不可能真去插拔物理网线。软件交换机可以随时创建虚拟网口、随时拔掉，天生为容器的&quot;用完即走&quot;设计。</p><p>Docker 出厂自带的第一台软件交换机，就叫 <strong>docker0</strong>。而官方文档说的&quot;<strong>默认 bridge 网络</strong>&quot;，就是指&quot;插在 docker0 这台交换机上的那个小区&quot;——我们前两课里的所有容器，住的都 是这个小区。</p><p>顺带解一个旧案：为什么第 2 课新容器拿到的是 <code>172.17.0.9</code> 而不是 <code>.2</code>？我在宿主机上跑 <code>docker ps</code> 看了一眼——这台机器上正跑着 <strong>7 个容器</strong>（上次课遗留的 box1、box2，还有别的项目留下的 redis、nginx、postgres）。7 个业主先占了门牌，新房客只能从 <code>.9</code> 开始拿号。</p><h2 id="实验二-网线的另一半-第-2-课彩蛋兑现" tabindex="-1"><a class="header-anchor" href="#实验二-网线的另一半-第-2-课彩蛋兑现"><span>实验二：网线的另一半（第 2 课彩蛋兑现）</span></a></h2><p>第 2 课我说 eth0 名字里的 <code>@if40</code> 是彩蛋，&quot;另一半在宿主机上&quot;。今天兑现。我在容器 box1 里和宿主机上<strong>各看了一眼网卡</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 容器 box1 里：</span></span>
<span class="line"><span>$ docker exec box1 ip addr show eth0</span></span>
<span class="line"><span>2: eth0@if38: &lt;BROADCAST,MULTICAST,UP,LOWER_UP,M-DOWN&gt; mtu 1500 qdisc noqueue</span></span>
<span class="line"><span>    link/ether a6:bf:2e:dd:55:d7 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 172.17.0.7/16 brd 172.17.255.255 scope global eth0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 宿主机上（节选）：</span></span>
<span class="line"><span>$ ip link show type veth</span></span>
<span class="line"><span>15: veth5efa696@if2: ... master docker0 ...</span></span>
<span class="line"><span>16: vethb08adfc@if2: ... master docker0 ...</span></span>
<span class="line"><span>31: veth2476840@if2: ... master docker0 ...</span></span>
<span class="line"><span>38: vetha5b2c4c@if2: ... master docker0 ...</span></span>
<span class="line"><span>...（共 7 根）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个关键读法：</p><ol><li><strong>编号互指</strong>：容器里 box1 的网卡叫 <code>eth0@if38</code>——它在说&quot;我的另一半，是宿主机上的 38 号接口&quot;。宿主机上恰好在第 38 号位置有一根 <code>vetha5b2c4c@if2</code>——它在说&quot;我的另一半，是那边的 2 号接口&quot;（box1 容器内 eth0 的编号正是 2）。一根线的两半，互相报出对方的编号。</li><li><strong><code>master docker0</code></strong>：宿主机上这 7 根 veth，全部标注 <code>master docker0</code>——意思是&quot;插在 docker0 这台交换机上&quot;。7 个容器，恰好 7 根线，一根不多。</li></ol><p>这个东西有个名字：<strong>veth pair（虚拟以太网设备对）</strong>——一对总是成对出现的虚拟网卡，<strong>从一头进去的数据包，会原封不动地从另一头出来</strong>。Docker 的用法是：生一对，一半塞进容器当 eth0，另一半插在 docker0 上。容器于是&quot;插上了交换机的网线&quot;。</p><h2 id="全景图-前-3-课的总装" tabindex="-1"><a class="header-anchor" href="#全景图-前-3-课的总装"><span>全景图（前 3 课的总装）</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>              宿主机（真电脑）</span></span>
<span class="line"><span>  ┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>  │        docker0 = 软件交换机 (172.17.0.1)  │── 物理网卡 eth0 ──→ 互联网</span></span>
<span class="line"><span>  │          │       │       │   ...        │</span></span>
<span class="line"><span>  │        veth38  veth15  veth16  （7 根）  │</span></span>
<span class="line"><span>  └──────────┼───────┼───────┼──────────────┘</span></span>
<span class="line"><span>             │       │       │      ← veth pair：一根虚拟网线的两半</span></span>
<span class="line"><span>         ┌───┴──┐ ┌──┴───┐ ┌─┴─────┐</span></span>
<span class="line"><span>         │ box1 │ │ box2 │ │ jzfz… │   容器 = 小电脑</span></span>
<span class="line"><span>         │ eth0 │ │ eth0 │ │ eth0  │   （每台有独立五件套）</span></span>
<span class="line"><span>         │ .0.7 │ │      │ │       │</span></span>
<span class="line"><span>         └──────┘ └──────┘ └───────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>到今天为止你学到的所有零散事实——五件套、大门 172.17.0.1、@if40、默认 bridge——现在全部装进这一张图里了。</p><h2 id="实验三-半开的门-第-1-课钩子兑现" tabindex="-1"><a class="header-anchor" href="#实验三-半开的门-第-1-课钩子兑现"><span>实验三：半开的门（第 1 课钩子兑现）</span></a></h2><p>第 1 课我说&quot;宿主机和容器之间有一扇半开的门&quot;。现在站在宿主机上，直接 ping 容器 box1 的门牌：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ ping -c 2 -W 1 172.17.0.7</span></span>
<span class="line"><span>PING 172.17.0.7 (172.17.0.7) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 172.17.0.7: icmp_seq=1 ttl=64 time=0.095 ms</span></span>
<span class="line"><span>64 bytes from 172.17.0.7: icmp_seq=2 ttl=64 time=0.037 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 172.17.0.7 ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 received, 0% packet loss</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通了。0.095 毫秒——比任何互联网延迟快几千倍，因为它压根没出过这台机器。</p><p>为什么宿主机能 ping 通&quot;另一台电脑&quot;？因为 <strong>docker0 就长在宿主机身上</strong>——宿主机自己也是小区的业主，跟容器是邻居，走的是第 2 课路由表里那条&quot;邻居直呼&quot;的规则。这就是&quot;半开&quot;的意思：<strong>宿主机 ↔ 容器是通的，外界 ↔ 容器是不通的</strong>。哪半边开着、哪半边关着，就是这个模块后面所有戏的来源。</p><h2 id="实验四-认个脸-docker-network-ls" tabindex="-1"><a class="header-anchor" href="#实验四-认个脸-docker-network-ls"><span>实验四（认个脸）：docker network ls</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker network ls</span></span>
<span class="line"><span>NETWORK ID     NAME                       DRIVER    SCOPE</span></span>
<span class="line"><span>7a200f8e3db9   bridge                     bridge    local</span></span>
<span class="line"><span>ac4fc42e94be   docker_gwbridge            bridge    local</span></span>
<span class="line"><span>de3d35e41f61   host                       host      local</span></span>
<span class="line"><span>d4438b6fccbf   new-api_new-api-network    bridge    local</span></span>
<span class="line"><span>6494333c3c80   none                       null      local</span></span>
<span class="line"><span>c88cb4c6fe5f   rabbitmq-cluster_default   bridge    local</span></span>
<span class="line"><span>232b31f9d168   rabbitmq_default           bridge    local</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是&quot;小区清单&quot;。三个是 Docker 出厂自带的：<code>bridge</code>（就是 docker0 小区）、<code>host</code>、<code>none</code>——后两个是第 11、12 课的主角，先混个脸熟。另外四个是我这台机器上别的项目（rabbitmq 集群等）留下的自定义小区——<strong>自定义小区长什么样，是第 8 课的大戏</strong>。命令细节第 16 课统一讲，今天只认脸。</p><h2 id="本课小结-2" tabindex="-1"><a class="header-anchor" href="#本课小结-2"><span>本课小结</span></a></h2><ul><li><code>docker0</code> = 宿主机上一块 bridge 类型的网卡 = 软件交换机 = 第 2 课那个网关 <code>172.17.0.1</code></li><li>&quot;默认 bridge 网络&quot; = 插在 docker0 上的小区；Docker 出厂自带</li><li><strong>veth pair</strong> = 成对虚拟网卡，一头在容器里当 eth0，一头插在 docker0 上；<code>@ifN</code> 是两半互相报出的对方编号</li><li>半开的门：宿主机 ↔ 容器<strong>通</strong>（docker0 是宿主机自己的网卡），外界 ↔ 容器<strong>不通</strong></li><li><code>docker network ls</code>：默认三件套 bridge / host / none</li></ul><h2 id="课后思考题-不查资料-用前三课推" tabindex="-1"><a class="header-anchor" href="#课后思考题-不查资料-用前三课推"><span>课后思考题（不查资料，用前三课推）</span></a></h2><p>同一个 box1，门牌 <code>172.17.0.7</code>：</p><ul><li>你的宿主机 ping 它，<strong>通</strong>（今天实测）；</li><li>你办公室<strong>同事的电脑</strong> ping <code>172.17.0.7</code>，通不通？</li></ul><p>答我两问：通/不通；<strong>为什么宿主机能、同事不能</strong>——用前三课学过的概念把推理链说出来。</p><hr><h2 id="【2026-08-22-·-第-4-次对话-插播问答-】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-4-次对话-插播问答-】"><span>【2026-08-22 · 第 4 次对话（插播问答）】</span></a></h2><h3 id="学生原话-3" tabindex="-1"><a class="header-anchor" href="#学生原话-3"><span>学生原话</span></a></h3><blockquote><p>你怎么知道 docker0的？为什一上来就直接 ip addr show docker0</p></blockquote><h3 id="操作记录-还原现场-实验-全部真机执行" tabindex="-1"><a class="header-anchor" href="#操作记录-还原现场-实验-全部真机执行"><span>操作记录（&quot;还原现场&quot;实验，全部真机执行）</span></a></h3><ol><li>宿主机 <code>ip -br addr</code>（无参数撒网）→ 全部网卡：<code>lo</code>、<code>eth0</code>（172.22.212.111/20，WSL 真网卡）、<code>docker0</code>（172.17.0.1/16）、<code>docker_gwbridge</code>（172.23.0.1/16，DOWN）、<code>br-c88cb4c6fe5f</code>（172.20.0.1/16，DOWN）、<code>br-d4438b6fccbf</code>（172.18.0.1/16，DOWN）、<code>br-232b31f9d168</code>（172.19.0.1/16，DOWN）、veth ×5（UP）。</li><li><code>docker network inspect bridge</code>（截取前 2000 字符）→ 账本 Options 里白纸黑字：<code>&quot;com.docker.network.bridge.name&quot;: &quot;docker0&quot;</code>、<code>&quot;com.docker.network.bridge.default_bridge&quot;: &quot;true&quot;</code>、<strong><code>&quot;com.docker.network.bridge.enable_ip_masquerade&quot;: &quot;true&quot;</code></strong>（第 5 课 NAT 魔术的官方预告）、IPAM：<code>Subnet 172.17.0.0/16, Gateway 172.17.0.1</code>。</li><li>名册核对 <code>docker network inspect bridge</code>（Containers 全量）→ 业主 5 名：jzfz-pg(.2)、jzfz-redis(.3)、lab-net-web(.4)、s-net-web(.5)、s-net-db(.6)——<strong>box1/box2 不在册</strong>，与第 3 课&quot;box1 拿着 172.17.0.7 且 ping 通&quot;矛盾。</li><li>对质 <code>docker inspect box1</code> → <code>NetworkMode=bridge</code>，但 <code>Networks.bridge</code> 的 <code>EndpointID=&quot;&quot;</code>、<code>IPAddress=&quot;&quot;</code>——endpoint 是空壳：上次课的容器经历过环境重启，Docker 账本已注销该连接，内核里 veth38 还插在 docker0 上（所以能 ping）。</li><li>本对话实录追加进本文件。</li></ol><h3 id="老师原文-插播问答-知识从哪来" tabindex="-1"><a class="header-anchor" href="#老师原文-插播问答-知识从哪来"><span>老师原文（插播问答：知识从哪来）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p>这个问题的质量，比你前三道答题都高。答题是&quot;验证你听懂了没有&quot;，这个问题是&quot;<strong>老师的东西是哪来的</strong>&quot;——这是从学生往大师走的那个岔路口。我分层诚实回答。</p><h2 id="第一层-老实话-我是先知道答案-再去看的" tabindex="-1"><a class="header-anchor" href="#第一层-老实话-我是先知道答案-再去看的"><span>第一层（老实话）：我是先知道答案，再去看的</span></a></h2><p>docker0 不是我&quot;发现&quot;的，是我&quot;背过&quot;的。它是 Docker 的<strong>官方固定默认行为</strong>：装完 Docker 必有这块网卡、名字必然叫 docker0、默认必然是 172.17.0.1/16——写死在官方文档里，全世界的工程师都背过。所以我上课&quot;一上来就直接 <code>ip addr show docker0</code>&quot;，那是<strong>确认</strong>，不是<strong>发现</strong>。你看到我行云流水，不是因为我会算命，是因为我备过课。</p><p>承认这个很重要：<strong>&quot;知道答案的人&quot;没什么了不起，了不起的是&quot;不知道时知道怎么找&quot;</strong>。所以第二层才是这节课真正要教你的。</p><h2 id="第二层-如果你不知道-你怎么自己找到它——三板斧" tabindex="-1"><a class="header-anchor" href="#第二层-如果你不知道-你怎么自己找到它——三板斧"><span>第二层：如果你不知道，你怎么自己找到它——三板斧</span></a></h2><h3 id="第一板斧-撒网-无参数命令-先看全貌" tabindex="-1"><a class="header-anchor" href="#第一板斧-撒网-无参数命令-先看全貌"><span>第一板斧：撒网（无参数命令，先看全貌）</span></a></h3><p><code>ip addr</code> 不带任何参数，就是把宿主机<strong>所有网卡一网打尽</strong>。我真机跑了（<code>ip -br addr</code> 是它的紧凑版）：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ ip -br addr</span></span>
<span class="line"><span>lo               UNKNOWN        127.0.0.1/8 ::1/128</span></span>
<span class="line"><span>eth0             UP             172.22.212.111/20 fe80::215:5dff:fe83:83a2/64</span></span>
<span class="line"><span>docker0          UP             172.17.0.1/16 fe80::64c5:efff:fec2:a788/64</span></span>
<span class="line"><span>docker_gwbridge  DOWN           172.23.0.1/16</span></span>
<span class="line"><span>br-c88cb4c6fe5f  DOWN           172.20.0.1/16</span></span>
<span class="line"><span>br-d4438b6fccbf  DOWN           172.18.0.1/16</span></span>
<span class="line"><span>br-232b31f9d168  DOWN           172.19.0.1/16</span></span>
<span class="line"><span>veth5efa696@if2  UP             fe80::6036:9bff:fec5:6fc5/64</span></span>
<span class="line"><span>vethb08adfc@if2  UP             fe80::a843:2eff:fe99:4227/64</span></span>
<span class="line"><span>...（共 5 根 UP 的 veth）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一台&quot;干净&quot;的 Linux，网卡应该只有 <code>lo</code> 和 <code>eth0</code> 两个。多出来的每一块都是&quot;嫌疑人&quot;。看名单——<code>docker0</code> 这名字自己都招了：<strong>docker 前缀</strong>，&quot;0&quot;是编号。旁边的 <code>br-c88cb4c6fe5f</code> 三个 <code>br-</code> 开头的，是第 3 课 <code>docker network ls</code> 里那几个自定义小区的交换机（<code>br-</code> + 网络 ID 前缀拼的设备名，第 8 课细讲）。<strong>撒网的收获：嫌疑人名单 + 名字里的线索。</strong></p><h3 id="第二板斧-对暗号-两个观察对上了-就不是巧合" tabindex="-1"><a class="header-anchor" href="#第二板斧-对暗号-两个观察对上了-就不是巧合"><span>第二板斧：对暗号（两个观察对上了，就不是巧合）</span></a></h3><p>撒网看到 docker0 的 IP 是 <code>172.17.0.1</code>——这个数字眼熟吗？<strong>第 2 课容器里的网关就是它</strong>。容器说&quot;我的大门是 172.17.0.1&quot;，宿主机上恰好有块网卡的 IP 是 172.17.0.1。两个独立观察撞在一起，就不是巧合，是同一件事的两面。</p><h3 id="第三板斧-查账-回到权威源头求证" tabindex="-1"><a class="header-anchor" href="#第三板斧-查账-回到权威源头求证"><span>第三板斧：查账（回到权威源头求证）</span></a></h3><p>猜测要拿证据坐实。Docker 自己的账本——<code>docker network inspect bridge</code>——我真机跑了，节选：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>&quot;Driver&quot;: &quot;bridge&quot;,</span></span>
<span class="line"><span>&quot;IPAM&quot;: { &quot;Config&quot;: [ { &quot;Subnet&quot;: &quot;172.17.0.0/16&quot;, &quot;Gateway&quot;: &quot;172.17.0.1&quot; } ] },</span></span>
<span class="line"><span>&quot;Options&quot;: {</span></span>
<span class="line"><span>  &quot;com.docker.network.bridge.default_bridge&quot;: &quot;true&quot;,</span></span>
<span class="line"><span>  &quot;com.docker.network.bridge.name&quot;: &quot;docker0&quot;,</span></span>
<span class="line"><span>  &quot;com.docker.network.bridge.enable_ip_masquerade&quot;: &quot;true&quot;,</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>白纸黑字：<code>&quot;com.docker.network.bridge.name&quot;: &quot;docker0&quot;</code>——Docker 亲口承认，bridge 小区绑定的内核设备就是 docker0。查账完毕，铁证。</p><p>顺手给你指个金矿：注意 Options 里那行 <strong><code>enable_ip_masquerade: true</code></strong>——&quot;启用 IP 伪装&quot;。这是第 5 课那个魔术的<strong>官方预告片</strong>，Docker 账本里自己写着的。到时候回来重读这一行，你会拍腿。</p><h2 id="课堂意外-白送的第四板斧-账本和现实打架时-对质" tabindex="-1"><a class="header-anchor" href="#课堂意外-白送的第四板斧-账本和现实打架时-对质"><span>课堂意外（白送的第四板斧：账本和现实打架时，对质）</span></a></h2><p>今天查账时撞出一个真意外，正好当教材。Docker 的业主名册里，bridge 小区在册的只有 5 个容器——<strong>box1、box2 不在册</strong>！但第 3 课我们明明 ping 通了 box1（172.17.0.7）。账本和现实打架了。</p><p>接着查 box1 自己的档案：<code>NetworkMode=bridge</code> 没错，但网络条目里 <code>EndpointID</code> 和 <code>IPAddress</code> <strong>全是空的</strong>——这是个空壳记录。定性：box1 是上次课遗留的容器，中间这台机器的环境重启过，Docker 重启后<strong>账本上把这条连接注销了，但内核里那根 veth38 还插在 docker0 上、IP 还挂着</strong>，所以照常能 ping。</p><p>给你一句能用十年的话：<strong>内核才是现实，Docker 只是记账员。账本会脱节，现实不会撒谎。</strong> 所以第四板斧是：当两条证据矛盾时，别急着信任何一方，继续往下查到它们汇合为止——今天&quot;ping 得通&quot;（内核现实）和&quot;不在册&quot;（Docker 账本）就是这样汇合的。</p><h2 id="本课小结-3" tabindex="-1"><a class="header-anchor" href="#本课小结-3"><span>本课小结</span></a></h2><p>你问&quot;我怎么知道 docker0&quot;，我给你的答案是一套<strong>可复制的探索流程</strong>：</p><ol><li><strong>撒网</strong>：无参数命令看全貌（<code>ip addr</code>），找陌生脸，读名字里的线索</li><li><strong>对暗号</strong>：新观察和旧观察撞上了，就不是巧合</li><li><strong>查账</strong>：回到权威源头（<code>docker network inspect</code>）拿铁证</li><li><strong>对质</strong>：证据矛盾时，查到汇合为止；内核是现实，账本是记录</li></ol><p>老师比你多的不是&quot;知道 docker0&quot;这个事实，是这四板斧。从下节课起，你也可以开始用它——下次你在任何陌生机器上看到一块叫 <code>br-</code> 什么的陌生网卡，你就已经知道怎么把它查个底掉了。</p><hr><p>上一课的思考题还挂着：<strong>同事的电脑 ping 172.17.0.7，通不通？为什么宿主机能、同事不能？</strong> 答完它，我们进第 4 课。</p><hr><h2 id="【2026-08-22-·-第-5-次对话-插播问答二-】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-5-次对话-插播问答二-】"><span>【2026-08-22 · 第 5 次对话（插播问答二）】</span></a></h2><h3 id="学生原话-4" tabindex="-1"><a class="header-anchor" href="#学生原话-4"><span>学生原话</span></a></h3><blockquote><p>ip link show type veth 这个究竟什么？</p></blockquote><h3 id="操作记录-全部真机执行" tabindex="-1"><a class="header-anchor" href="#操作记录-全部真机执行"><span>操作记录（全部真机执行）</span></a></h3><ol><li>三连对照实验首跑：<code>ip -br link</code> / <code>ip -br link type veth</code> / <code>ip -br link type bridge</code> → 后两条报错 <code>Command &quot;type&quot; is unknown</code>（此版本 iproute2 不接受 <code>-br</code> 与 <code>type</code> 过滤组合）；全量清单正常：11 块（eth0、docker0、docker_gwbridge、br-×3、veth×5）。</li><li>正确语法重跑：<code>ip link show type veth</code>（grep 编号行）→ <strong>只剩 5 根</strong> veth，全部 <code>master docker0</code>；<code>ip link show type bridge</code> → <strong>5 台交换机</strong>（docker0、docker_gwbridge、br-c88/br-d44/br-232）。</li><li>新意外：第 3 课同样命令出 7 根 veth，现在 5 根——box1/box2 的 38/39 号 veth 消失。验证三连：宿主机 <code>ping 172.17.0.7</code> → 100% 丢包；<code>docker exec box1</code> → <code>Error: container ... is not running</code>；<code>docker ps -a --filter name=box</code> → <strong>box1/box2 均 Exited (0)，24 分钟前退出</strong>。</li><li>结论：撤销第 4 次对话中&quot;环境重启导致账本脱节&quot;的定性。真相：busybox 容器跑的命令结束、正常退出；退出时容器网络空间销毁 → veth 成对拆除 → Docker 账本除名。ping 由通变不通、名册除名、endpoint 空壳，全部是<strong>正常清理流程</strong>，不是脱节。</li><li>本对话实录追加进本文件。</li></ol><h3 id="老师原文-命令拆解-当堂纠错" tabindex="-1"><a class="header-anchor" href="#老师原文-命令拆解-当堂纠错"><span>老师原文（命令拆解 + 当堂纠错）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p>你问的这条命令，是第 3 课实验二的&quot;取材命令&quot;。它值得单独拆一课，因为拆完它，<code>ip</code> 命令<strong>全家</strong>你都会读了——那是你以后在网络世界天天用的瑞士军刀。</p><h2 id="一、逐词拆解-ip-link-show-type-veth" tabindex="-1"><a class="header-anchor" href="#一、逐词拆解-ip-link-show-type-veth"><span>一、逐词拆解：<code>ip link show type veth</code></span></a></h2><p>先给你一个语法公式，Linux 的 <code>ip</code> 命令全家族都长这样：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>ip   &lt;对象&gt;   &lt;动作&gt;   [筛选条件]</span></span>
<span class="line"><span>     link     show     type veth</span></span>
<span class="line"><span>     ↓        ↓        ↓</span></span>
<span class="line"><span>   操作谁？  干什么？  只挑哪些？</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong><code>ip</code></strong>：工具本身。Linux 网络的一切物件——网卡、地址、路由——都用它查看和配置。</li><li><strong><code>link</code></strong>：对象。&quot;link&quot;指链路层设备，说白了就是<strong>网卡这个物件本身</strong>。它有两个亲兄弟，你前几课全见过：<code>ip addr</code>（看网卡上挂的 IP 地址）和 <code>ip route</code>（看路由表）。<strong>link 管物件，addr 管门牌，route 管出门规则</strong>——三兄弟各管一层。</li><li><strong><code>show</code></strong>：动作，&quot;显示&quot;。不写它也默认是 show（<code>ip link</code> = <code>ip link show</code>）。</li><li><strong><code>type veth</code></strong>：筛选条件，<strong>只显示&quot;型号&quot;为 veth 的设备</strong>。这是今天的核心，下面细讲。</li></ul><h2 id="二、核心概念-网卡是一-大类-每块都有型号" tabindex="-1"><a class="header-anchor" href="#二、核心概念-网卡是一-大类-每块都有型号"><span>二、核心概念：网卡是一&quot;大类&quot;，每块都有型号</span></a></h2><p>很多人以为&quot;网卡&quot;就是一种东西。错——网卡是一<strong>大类设备</strong>，每块网卡都有一个<strong>型号（type）</strong>，就像&quot;车&quot;是大类，下面分轿车、卡车、公交。</p><p>你这台宿主机上，此刻就跑着好几种型号。我做了一组对照实验（全量 vs 按型号筛）：</p><p><strong>A. 全量——所有网卡一网打尽：</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ ip -br link</span></span>
<span class="line"><span>eth0             UP             00:15:5d:83:83:a2 ...</span></span>
<span class="line"><span>docker0          UP             66:c5:ef:c2:a7:88 ...</span></span>
<span class="line"><span>docker_gwbridge  DOWN           2a:d8:8b:59:c0:e9 ...</span></span>
<span class="line"><span>br-c88cb4c6fe5f  DOWN           d6:29:9c:72:82:85 ...</span></span>
<span class="line"><span>br-d4438b6fccbf  DOWN           66:d2:84:73:7b:61 ...</span></span>
<span class="line"><span>br-232b31f9d168  DOWN           5e:64:53:2c:a7:32 ...</span></span>
<span class="line"><span>veth5efa696@if2  UP             62:36:9b:c5:6f:c5 ...</span></span>
<span class="line"><span>vethb08adfc@if2  UP             aa:43:2e:99:42:27 ...</span></span>
<span class="line"><span>...（veth 共 5 根）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>B. 只看 veth 型号——<code>ip link show type veth</code>：</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>15: veth5efa696@if2: ... master docker0 state UP ...</span></span>
<span class="line"><span>16: vethb08adfc@if2: ... master docker0 state UP ...</span></span>
<span class="line"><span>31: veth2476840@if2: ... master docker0 state UP ...</span></span>
<span class="line"><span>32: veth917df32@if2: ... master docker0 state UP ...</span></span>
<span class="line"><span>33: veth1d30c12@if2: ... master docker0 state UP ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>C. 只看 bridge 型号——<code>ip link show type bridge</code>：</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>4: docker0:          ... state UP ...</span></span>
<span class="line"><span>5: docker_gwbridge:  ... state DOWN ...</span></span>
<span class="line"><span>7: br-c88cb4c6fe5f:  ... state DOWN ...</span></span>
<span class="line"><span>8: br-d4438b6fccbf:  ... state DOWN ...</span></span>
<span class="line"><span>9: br-232b31f9d168:  ... state DOWN ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看出规律了吗：<strong>A = B + C + eth0</strong>（物理网卡）。<code>type</code> 过滤器就像文件管理器里&quot;只显示 PDF&quot;——网卡清单按型号分拣，每次只捞一种。</p><p>你机器上现有的三种型号，正好就是 Docker 网络世界的三种积木：</p><table><thead><tr><th>型号（type）</th><th>是什么</th><th>Docker 里的角色</th></tr></thead><tbody><tr><td><code>eth0</code>（物理/虚拟网卡）</td><td>普通网卡，有门牌能上网</td><td>宿主机联外网的腿</td></tr><tr><td><code>bridge</code></td><td>软件交换机</td><td>docker0、br-xxx 小区的交换机</td></tr><tr><td><code>veth</code></td><td>成对网线</td><td>容器插交换机的那根线</td></tr></tbody></table><p><strong>第 3 课的全景图，翻译成今天的型号语言就是：用 veth（网线）把容器和 bridge（交换机）连起来，交换机再通过物理网卡（腿）出门。Docker 网络 = 三种积木的拼装。</strong></p><p>所以当时为什么用 <code>type veth</code>：宿主机上十来块网卡，veth 混在里面，按型号一筛，&quot;网线的另一半们&quot;全部现形，还每根都标着 <code>master docker0</code>（插在哪台交换机上）。撒网技术第二式：<strong>按型号捞</strong>。</p><h2 id="三、课堂意外终章-veth-从-7-根变-5-根-以及老师的错误" tabindex="-1"><a class="header-anchor" href="#三、课堂意外终章-veth-从-7-根变-5-根-以及老师的错误"><span>三、课堂意外终章：veth 从 7 根变 5 根，以及老师的错误</span></a></h2><p>你看到了：第 3 课这条命令输出 <strong>7 根</strong> veth，今天只剩 <strong>5 根</strong>。box1/box2 的 38、39 号网线，没了。我顺手做了验证：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ ping -c 2 -W 1 172.17.0.7</span></span>
<span class="line"><span>2 packets transmitted, 0 received, 100% packet loss    ← 第 3 课还是 0% 丢包！</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ docker exec box1 ip -br link</span></span>
<span class="line"><span>Error response from daemon: container ... is not running</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ docker ps -a --filter name=box</span></span>
<span class="line"><span>box2   Exited (0)   24 minutes ago</span></span>
<span class="line"><span>box1   Exited (0)   24 minutes ago</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真相：box1/box2 里跑的命令结束了，<strong>两个容器 24 分钟前正常退出</strong>。容器一退出：它的网络空间销毁 → veth 这根&quot;成对网线&quot;一端报废、整对拆除 → IP 还回号码池 → Docker 账本除名。所以 veth 少两根、ping 不通、名册除名、endpoint 空壳——<strong>全是正常清理流程，环环自洽</strong>。</p><p>现在说我的错误。上一堂课（第 4 次对话），我看到&quot;名册除名 + endpoint 空壳&quot;，结合&quot;这台 WSL 以前杀过容器&quot;的记忆，给你讲了一个&quot;环境重启导致账本脱节&quot;的故事。<strong>那个定性是错的。</strong> 真相平凡得多：容器就是退出了。我错在哪？<strong>我当时没跑 <code>docker ps -a</code></strong>——一条十秒钟的命令就能看到&quot;Exited (0) 24 minutes ago&quot;，我却停在了一个&quot;讲得通&quot;的故事上。这恰好违反了我自己教你的第四板斧：查到证据链闭合为止。</p><p>所以今天给你的金句，比上一课那句更狠：</p><blockquote><p><strong>讲得通的解释 ≠ 对的解释。证据链没闭合之前，任何&quot;合理的故事&quot;都只是嫌疑犯。</strong></p></blockquote><p>这个错误我留着不改（实录里原样放着），因为它比一百次正确更有教学价值——你以后也会犯同样的错：脑补一个顺滑的解释，然后停止查证。记住今天的 box1。</p><h2 id="本课小结-4" tabindex="-1"><a class="header-anchor" href="#本课小结-4"><span>本课小结</span></a></h2><ul><li><code>ip</code> 语法公式：<code>ip &lt;对象&gt; &lt;动作&gt; [筛选条件]</code>；三兄弟 <code>link</code>（物件）/ <code>addr</code>（门牌）/ <code>route</code>（出门规则）</li><li>网卡分型号：<code>type</code> 过滤 = 文件管理器的&quot;按类型筛选&quot;</li><li>Docker 网络三种积木：物理网卡（腿）、bridge（交换机）、veth（网线）</li><li>容器退出 → veth 成对拆除 → IP 回池 → 账本除名，全链自动</li><li>老师当堂纠错：证据链闭合前，别信&quot;讲得通&quot;的故事</li></ul><hr><p><strong>思考题更新</strong>：box1 已退房，题目例子换成在册住户 <strong>jzfz-pg（172.17.0.2）</strong>——你的宿主机 ping 它通，<strong>同事的电脑</strong> ping 172.17.0.2 通不通？为什么宿主机能、同事不能？答完进第 4 课。</p><hr><h2 id="【2026-08-22-·-第-6-次对话】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-6-次对话】"><span>【2026-08-22 · 第 6 次对话】</span></a></h2><h3 id="学生原话-5" tabindex="-1"><a class="header-anchor" href="#学生原话-5"><span>学生原话</span></a></h3><blockquote><p>根据刚刚学到的 veth虚拟网线，容器和宿主机是有一条网线相连的，但是容器和容器之间没有网线相连，所以容器之间不能ping得通</p></blockquote><h3 id="操作记录-第-4-课实验-全部真机执行" tabindex="-1"><a class="header-anchor" href="#操作记录-第-4-课实验-全部真机执行"><span>操作记录（第 4 课实验，全部真机执行）</span></a></h3><ol><li>起两个新容器：<code>docker run -d --name lab-a busybox sleep 1800</code>、<code>lab-b</code> 同款 → lab-a 得 <code>172.17.0.8</code>、lab-b 得 <code>172.17.0.9</code>（首次取 IP 的模板 <code>.NetworkSettings.IPAddress</code> 报错 map no entry，换 <code>{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}</code> 成功）。</li><li>互 ping：<code>lab-a ping 172.17.0.9</code> → 2 发 2 收 0% 丢包（0.083ms avg）；<code>lab-b ping 172.17.0.8</code> → 同样 0% 丢包（0.085ms avg）。<strong>双向全通。</strong></li><li><code>docker exec lab-a cat /proc/net/arp</code> → ARP 表里有一条：<code>172.17.0.9 → f6:b1:0e:b7:a8:97</code>（lab-b 的 MAC）。</li><li>数 veth：<code>ip link show type veth</code> 编号行 <code>grep -c</code> → <strong>8 根</strong>。预期 5+2=7，对不上 → 查 <code>docker ps</code>：8 个容器在跑——<strong>box1 复活了</strong>（Up 9 minutes）。查 restart 策略：<code>box1 RestartPolicy=no</code>，<code>StartedAt=2026-08-21T23:58:13Z</code>（北京 07:58，与 Up 9min 吻合）→ 是被某种方式手动 start 的，非策略自动拉起；谁拉的现有证据查不到，到此为止。8 容器 ↔ 8 根 veth，账平。</li><li>本对话实录追加进本文件。</li></ol><h3 id="老师原文-判卷-第-4-课" tabindex="-1"><a class="header-anchor" href="#老师原文-判卷-第-4-课"><span>老师原文（判卷 + 第 4 课）</span></a></h3><p>（以下与控制台输出一字不差）</p><hr><p><strong>先判卷。</strong></p><p>你的推理链：veth 连着容器和宿主机 → 容器之间没有直连网线 → 所以容器之间 ping 不通。</p><p>推理的<strong>形式</strong>很漂亮——用刚学的概念做预测，这正是学网络该有的姿势。前半句对了一半，结论<strong>错</strong>。错在哪？一句话：<strong>你把&quot;交换机&quot;当成了&quot;宿主机&quot;本身。</strong></p><p>修正模型：veth 这根网线，不是插在&quot;宿主机&quot;上的，是插在 <strong>docker0（那台软件交换机）</strong>上的。docker0 确实长在宿主机身上，但它的角色是<strong>交换机</strong>，不是网线的终点。而交换机存在的意义、它天生的本职工作就是一件事：<strong>让插在它身上的所有设备互通</strong>。</p><p>换个类比：宿主机是一栋办公楼，docker0 是楼里机房的那台交换机，veth 是每个工位到机房的网线。工位 A 和工位 B 之间确实没有直连网线——<strong>你这半句说对了</strong>——但它们的线都插在同一台交换机上。在同一个交换机上的设备，就是同一间屋里的邻居，喊一嗓子彼此都听得见。</p><p>不用信我嘴说。60 秒实验，让事实判卷。</p><h2 id="第-4-课-默认-bridge-实战——两个容器用-ip-互-ping" tabindex="-1"><a class="header-anchor" href="#第-4-课-默认-bridge-实战——两个容器用-ip-互-ping"><span>第 4 课：默认 bridge 实战——两个容器用 IP 互 ping</span></a></h2><h3 id="实验设计" tabindex="-1"><a class="header-anchor" href="#实验设计"><span>实验设计</span></a></h3><p>起两个新容器，用最土的办法验证你的预测：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker run -d --name lab-a busybox sleep 1800</span></span>
<span class="line"><span>$ docker run -d --name lab-b busybox sleep 1800</span></span>
<span class="line"><span>$ docker inspect -f &quot;{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}&quot; lab-a   → 172.17.0.8</span></span>
<span class="line"><span>$ docker inspect -f &quot;...&quot; lab-b                                                        → 172.17.0.9</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>你的预测：ping 不通。开牌：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker exec lab-a ping -c 2 -W 2 172.17.0.9</span></span>
<span class="line"><span>64 bytes from 172.17.0.9: seq=0 ttl=64 time=0.097 ms</span></span>
<span class="line"><span>64 bytes from 172.17.0.9: seq=1 ttl=64 time=0.070 ms</span></span>
<span class="line"><span>--- 172.17.0.9 ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 packets received, 0% packet loss</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ docker exec lab-b ping -c 2 -W 2 172.17.0.8</span></span>
<span class="line"><span>2 packets transmitted, 2 packets received, 0% packet loss</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>双向全通，0% 丢包，0.09 毫秒。</strong> 你的预测被实验打脸了——恭喜，这是学实验科学最好的时刻。</p><h3 id="铁证-lab-a-的-arp-邻居表" tabindex="-1"><a class="header-anchor" href="#铁证-lab-a-的-arp-邻居表"><span>铁证：lab-a 的 ARP 邻居表</span></a></h3><p>光&quot;通&quot;还不够，我再给你一个更硬的证据。查 lab-a 内心深处的邻居记录：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>$ docker exec lab-a cat /proc/net/arp</span></span>
<span class="line"><span>IP address       HW type     Flags       HW address            Mask     Device</span></span>
<span class="line"><span>172.17.0.9       0x1         0x2         f6:b1:0e:b7:a8:97     *        eth0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>解释一下你看到什么了：网络底层不认 IP 认 MAC（第 2 课那个&quot;网卡出厂编号&quot;）。同一根线路段上的设备互相通信前，会先<strong>广播喊话</strong>：&quot;谁是 172.17.0.9？把你的 MAC 报给我！&quot;——这种喊话<strong>只有同一链路段上的设备听得到</strong>（它不会被转发到网关外面去）。lab-a 的表里清清楚楚记着 lab-b 的 MAC <code>f6:b1:0e:b7:a8:97</code>——说明 lab-a 是通过&quot;同一根线路段上的广播&quot;直接找到 lab-b 的。<strong>它俩在同一个链路段上，中间没有任何网关。</strong>这就是&quot;插在同一台交换机上&quot;的铁证。</p><h3 id="第-2-课伏笔兑现-什么叫-邻居" tabindex="-1"><a class="header-anchor" href="#第-2-课伏笔兑现-什么叫-邻居"><span>第 2 课伏笔兑现：什么叫&quot;邻居&quot;</span></a></h3><p>还记得第 2 课路由表那两行吗？</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>default via 172.17.0.1 dev eth0          ← 其余的，交大门</span></span>
<span class="line"><span>172.17.0.0/16 dev eth0 scope link ...    ← 邻居，直接喊话</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>当时我说&quot;邻居 = 同小区住户&quot;，含糊带过。今天可以给出精确版了：<strong>&quot;邻居&quot;就是&quot;插在同一台交换机上的设备&quot;</strong>。lab-a ping lab-b，路由表一查：目的地 172.17.0.9 在 172.17.0.0/16 里 → 走第二条规则 → 直接从 eth0 喊话（ARP 广播找 MAC）→ docker0 这台交换机把喊话转给 lab-b 的网线 → 完成。<strong>全程没碰大门，没出小区。</strong></p><h3 id="包的完整旅程-全景图升级" tabindex="-1"><a class="header-anchor" href="#包的完整旅程-全景图升级"><span>包的完整旅程（全景图升级）</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>lab-a                                  lab-b</span></span>
<span class="line"><span>┌──────────┐                          ┌──────────┐</span></span>
<span class="line"><span>│ eth0     │                          │ eth0     │</span></span>
<span class="line"><span>│ 172.17.0.8│                         │ 172.17.0.9│</span></span>
<span class="line"><span>└────┬─────┘                          └────▲─────┘</span></span>
<span class="line"><span>     │ veth（网线的一半）                   │</span></span>
<span class="line"><span>     ▼                                    │ veth</span></span>
<span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                docker0 交换机                  │  ← 在宿主机肚子里</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>包从 lab-a 的 eth0 出发 → 顺着 veth 网线滑到 docker0 → docker0 查着 MAC 把它从另一根 veth 转给 lab-b → lab-b 的 eth0 收到。<strong>容器之间确实没有直连网线，但交换机替它们&quot;接了头&quot;。</strong></p><h3 id="官方文档佐证-一颗延时炸弹" tabindex="-1"><a class="header-anchor" href="#官方文档佐证-一颗延时炸弹"><span>官方文档佐证 + 一颗延时炸弹</span></a></h3><p>官方文档原话（意译）：<em>默认配置下，默认 bridge 上的容器之间可以用<strong>容器 IP 地址</strong>无限制地互相访问。它们<strong>不能通过名字互相访问</strong>。</em></p><p>前半句今天兑现了。后半句请抄在便签上贴显示器边：<strong>&quot;不能用名字互访&quot;</strong>——这是默认 bridge 最大的坑，第 7 课它将引爆一场真实事故，第 8 课用它换来自定义网络的真谛。</p><h3 id="课堂支线-veth-为什么数出-8-根" tabindex="-1"><a class="header-anchor" href="#课堂支线-veth-为什么数出-8-根"><span>课堂支线：veth 为什么数出 8 根</span></a></h3><p>实验时我数 veth：预期 5 旧 + 2 新 = 7 根，实际 <strong>8 根</strong>。按第 5 次对话立的规矩，数字对不上就查——<code>docker ps</code> 一看：8 个容器，其中 <strong>box1 复活了</strong>（Up 9 minutes）。查它的重启策略是 <code>no</code>，说明不是自动拉起，是被某种方式重新 start 的（谁拉的，现有证据查不到，到此为止，不编故事）。重要的是事实链完整：<strong>8 个容器 ↔ 8 根 veth，一一对应，账平了</strong>。顺带这也实证了上一课的逆过程：<strong>容器启动 → veth 自动重建 → 重新入册</strong>。</p><h2 id="本课小结-5" tabindex="-1"><a class="header-anchor" href="#本课小结-5"><span>本课小结</span></a></h2><ul><li>容器 ↔ 宿主机之间<strong>没有</strong>点对点网线；veth 是&quot;容器 ↔ docker0 交换机&quot;的网线</li><li>同一 bridge 网络上的容器 = 同一台交换机上的邻居 = 同一链路段 → <strong>用 IP 互 ping 通</strong>（实测双向 0% 丢包）</li><li>ARP 表是&quot;同一链路段&quot;的铁证：里面有对方 MAC = 广播直呼过 = 没过网关</li><li>第 2 课&quot;邻居直呼&quot;规则兑现：邻居 = 同一台交换机上的设备</li><li>官方文档：默认 bridge 容器间<strong>IP 互访无限制</strong>、<strong>名字互访不行</strong>（第 7 课炸弹）</li></ul><h2 id="课后思考题-第-5-课的门票" tabindex="-1"><a class="header-anchor" href="#课后思考题-第-5-课的门票"><span>课后思考题（第 5 课的门票）</span></a></h2><p>lab-a 现在能和 lab-b 互通了。那它能不能出门？在 lab-a 里 <code>ping 223.5.5.5</code>（阿里 DNS，公网地址），你觉得通不通？</p><p>更关键的是第二问：<strong>如果通了</strong>——lab-a 发出的包裹，寄件人地址写的是 <code>172.17.0.8</code>。可是 172.17.x.x 这种门牌在互联网上<strong>根本不存在</strong>（它是&quot;私网门牌&quot;，出了小区没人认识）。那阿里的回程包裹，是怎么一路找到这台小电脑的？</p><p>提示：答案就藏在第 4 次对话查账时你见过的那一行 Docker 账本里。</p><hr><h2 id="【2026-08-22-·-第-7-次对话-插播问答三-】" tabindex="-1"><a class="header-anchor" href="#【2026-08-22-·-第-7-次对话-插播问答三-】"><span>【2026-08-22 · 第 7 次对话（插播问答三）】</span></a></h2><h3 id="学生原话-6" tabindex="-1"><a class="header-anchor" href="#学生原话-6"><span>学生原话</span></a></h3><blockquote><p>root@pc3507:~# docker exec box1 ip addr show eth0<br> 2: eth0@if50: &lt;BROADCAST,MULTICAST,UP,LOWER_UP,M-DOWN&gt; mtu 1500 qdisc noqueue<br> link/ether 0a:da:f1:d1:9f:9c brd ff:ff:ff:ff:ff:ff<br> inet 172.17.0.7/16 brd 172.17.255.255 scope global eth0<br> valid_lft forever preferred_lft forever<br> root@pc3507:~# ip link show type veth<br> 15: veth5efa696@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether 62:36:9b:c5:6f:c5 brd ff:ff:ff:ff:ff:ff link-netnsid 0<br> 16: vethb08adfc@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether aa:43:2e:99:42:27 brd ff:ff:ff:ff:ff:ff link-netnsid 1<br> 31: veth2476840@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether 42:1a:96:83:b7:82 brd ff:ff:ff:ff:ff:ff link-netnsid 2<br> 32: veth917df32@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether c2:28:43:92:ca:27 brd ff:ff:ff:ff:ff:ff link-netnsid 3<br> 33: veth1d30c12@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether 4e:ac:7f:b6:0c:ed brd ff:ff:ff:ff:ff:ff link-netnsid 4<br> 50: veth1a7c2fb@if2: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue master docker0 state UP mode DEFAULT group default<br> link/ether 3e:05:ac:2c:11:56 brd ff:ff:ff:ff:ff:ff link-netnsid 5</p><p>你刚刚不是说容器里面是 eth0,然后和对应编号的什么绑定在一起了么，和docker0有什么关系</p></blockquote><p>（学生首次<strong>自主上机</strong>，在同一台 PC3507 的 WSL 环境跑了两条课上的命令）</p><h3 id="老师原文-veth-的两层关系" tabindex="-1"><a class="header-anchor" href="#老师原文-veth-的两层关系"><span>老师原文（veth 的两层关系）</span></a></h3><hr><p>先记一笔：<strong>这是你第一次自己上机拿证据来问问题，而不是听我讲。</strong>这个转折比这个问题的答案重要十倍——你已经开始用第 4 次对话那套&quot;撒网—对暗号&quot;了。而且运气极好：你这两条输出里，正好藏着你要的答案，还藏着两个连我都没安排的彩蛋。逐个拆。</p><h2 id="你混淆的-一根线上的两层关系" tabindex="-1"><a class="header-anchor" href="#你混淆的-一根线上的两层关系"><span>你混淆的：一根线上的两层关系</span></a></h2><p>你的疑问其实是：&quot;eth0@if50 这个&#39;编号绑定&#39;，跟 docker0 是什么关系？&quot;</p><p>答案是：<strong>它们是两层完全不同的关系，在你自己的输出里用两种不同的标记写着，你把它们看成一层了。</strong></p><h3 id="第一层-if50-if2-——网线内部的事-跟-docker0-无关" tabindex="-1"><a class="header-anchor" href="#第一层-if50-if2-——网线内部的事-跟-docker0-无关"><span>第一层：<code>@if50</code> / <code>@if2</code> ——网线<strong>内部</strong>的事（跟 docker0 无关）</span></a></h3><p>看你自己抓到的这对：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>容器 box1 里：2: eth0@if50          ← &quot;我是 2 号，我的另一半是 50 号&quot;</span></span>
<span class="line"><span>宿主机上：  50: veth1a7c2fb@if2     ← &quot;我是 50 号，我的另一半是 2 号&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>@ifN</code> 是 veth 网线<strong>两半互相报对方编号</strong>——纯粹是这一对内部的事。一对 veth 生来就连通：从一端塞进去的包，会原封不动从另一端掉出来，<strong>哪怕这根线哪儿都没插</strong>。这层关系里，docker0 没有任何戏份。</p><h3 id="第二层-master-docker0-——网线插上交换机的事" tabindex="-1"><a class="header-anchor" href="#第二层-master-docker0-——网线插上交换机的事"><span>第二层：<code>master docker0</code> ——网线<strong>插上交换机</strong>的事</span></a></h3><p>再看你的每根 veth 后面都拖着的那半句：<code>master docker0</code>。这句话的主语是<strong>宿主机那半根线</strong>（veth1a7c2fb），意思是：&quot;我把自己插在了 docker0 这台交换机的端口上。&quot;——这才是&quot;和 docker0 的关系&quot;。</p><h3 id="合起来-一条完整的链" tabindex="-1"><a class="header-anchor" href="#合起来-一条完整的链"><span>合起来：一条完整的链</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>   box1 容器                                  宿主机</span></span>
<span class="line"><span>┌───────────────────┐</span></span>
<span class="line"><span>│ 2: eth0@if50       │ ← 网线的一半（容器侧）</span></span>
<span class="line"><span>└─────────┬─────────┘</span></span>
<span class="line"><span>          │ ══════ veth pair（@if50 与 @if2 互相报对方编号）══════</span></span>
<span class="line"><span>┌─────────▼─────────┐</span></span>
<span class="line"><span>│ 50: veth1a7c2fb@if2│ ← 网线的另一半（宿主机侧）</span></span>
<span class="line"><span>│    master docker0  │ ← 这一半插在交换机上</span></span>
<span class="line"><span>└─────────┬─────────┘</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>    ┌───────────┐</span></span>
<span class="line"><span>    │  docker0  │  ← 交换机（bridge 型号）</span></span>
<span class="line"><span>    └───────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一句话总结：<strong><code>@ifN</code> 是线自己的两根芯，<code>master docker0</code> 是线插上了哪台机器。容器里的 eth0 从头到尾不认识 docker0——它只认识自己手里那根线，线那头通到哪，是 Docker 布线时决定的。</strong></p><h2 id="本课小结-6" tabindex="-1"><a class="header-anchor" href="#本课小结-6"><span>本课小结</span></a></h2><ul><li>veth 两层关系两层标记：<code>@ifN</code> = 线的两半互报编号（线的内部）；<code>master docker0</code> = 线插上交换机（线与交换机）</li><li>容器 eth0 不直接认识 docker0，只认识自己的网线</li><li>容器重启 = 拆旧线、做新线、重租门牌（IP 可能相同可能不同，不保证）</li><li>从 veth 清清单可以反推容器存活数——账本会说话</li></ul><hr><p>第 6 课的思考题还挂着：<strong>lab-a 里 ping 223.5.5.5 通不通？公网不认识 172.17.0.8 这个私网门牌，回程包裹是怎么找到它的？</strong>——提示再看一眼：第 4 次对话 Docker 账本里的那一行。答完进第 5 课。</p><hr>`,303)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};